To implement a debounced async API call with cancellation support in JavaScript, we need to debounce the function such that it will only execute after a specified delay without being called again. Additionally, we will add support for canceling the previous call before making a new one. 

Here's a sample implementation:

```javascript
function debounceAsync(fn, delay) {
    let timeoutId;
    let currentPromise = null;

    return function(...args) {
        // Cancel the previous timeout (debouncing)
        if (timeoutId) {
            clearTimeout(timeoutId);
        }

        // Cancel the previous promise if it's still pending
        if (currentPromise) {
            currentPromise.cancel(); // Assuming your API function returns an object with a cancel method
        }

        // Create a new promise and attach cancel functionality
        const cancellable = createCancellablePromise(() => fn(...args));
        currentPromise = cancellable.promise;

        timeoutId = setTimeout(() => {
            currentPromise = cancellable.promise;
        }, delay);

        return currentPromise;
    };
}

// Helper function to create a cancellable promise
function createCancellablePromise(fn) {
    let cancel;
    const promise = new Promise((resolve, reject) => {
        cancel = () => {
            reject({ isCanceled: true });
        };

        fn()
            .then(resolve)
            .catch(reject);
    });

    return {
        promise,
        cancel,
    };
}

// Example API call function
async function fetchData(query) {
    // Simulate an API call with a delay
    return new Promise((resolve) => {
        setTimeout(() => {
            resolve(`Data for ${query}`);
        }, 1000);
    });
}

// Debounced version of the fetchData function
const debouncedFetchData = debounceAsync(fetchData, 300);

// Using the debounced function
debouncedFetchData('query1').then(console.log).catch((err) => {
    if (err.isCanceled) {
        console.log('Fetch canceled');
    } else {
        console.error('Error:', err);
    }
});

// You can call the debounced function repeatedly
debouncedFetchData('query2');
debouncedFetchData('query3');
```

### Explanation:

1. **debounceAsync Function**: It takes a function `fn` and a delay duration. We maintain a `timeoutId` for delaying the API calls and a `currentPromise` for managing the currently active API call.

2. **Cancellable Promise**: The

`createCancellablePromise` function creates a promise that can be canceled. It provides a way to reject the promise if the cancellation method is called. 

3. **Debouncing Logic**: Inside the `debounceAsync` function, whenever the returned function is invoked:
   - If there's an existing `timeoutId`, it clears the timeout to prevent the previous call from executing.
   - It checks if there's a currently pending promise (`currentPromise`). If it exists, it cancels that promise by calling the `cancel` method on it.
   - It creates a new cancellable promise from `fn`, which will represent the future API call.
   - A new timeout is set up, and after the specified delay, it updates the `currentPromise` to the latest promise.

4. **Example Function**: The `fetchData` function simulates an asynchronous API call that resolves after a delay of 1000 milliseconds. 

5. **Usage**: The `debouncedFetchData` is the debounced version of `fetchData`. When invoked multiple times, each call resets the debounce timer, and only the final call after the specified delay will execute. If a new call interrupts an ongoing one, it cancels the previous call and ensures that only the latest query is executed.

By following these principles, we achieve both debouncing of the API calls and robust cancellation support, ensuring efficient resource use and better control over asynchronous operations in JavaScript applications. 

Here's a recap of how to use the debounced function:

```javascript
// Usage of the debounced function (calls will be consolidated)
debouncedFetchData('query1').then(console.log).catch(handleFetchError);
debouncedFetchData('query2');
debouncedFetchData('query3');

// A simple error handler
function handleFetchError(err) {
    if (err.isCanceled) {
        console.log('Fetch canceled');
    } else {
        console.error('Error:', err);
    }
}
```

In the example above, if `debouncedFetchData` is called with 'query2' and 'query3' quickly after 'query1', only the last call (with 'query3') will go through after the debounce delay, while any ongoing promise will be canceled.

Here is a complete implementation of the `createCancellablePromise` function along with the `debounceAsync` logic and the example `fetchData` function. This will demonstrate how to create a cancellable promise and use it effectively in conjunction with debouncing.

### Implementation

```javascript
function createCancellablePromise(executor) {
    let cancel;

    const promise = new Promise((resolve, reject) => {
        cancel = () => {
            reject({ isCanceled: true });
        };

        executor(resolve, reject);
    });

    return {
        promise,
        cancel
    };
}

function debounceAsync(fn, delay) {
    let timeoutId;
    let currentPromise;

    return function(...args) {
        if (timeoutId) {
            clearTimeout(timeoutId);
        }

        if (currentPromise) {
            currentPromise.cancel();
        }

        currentPromise = createCancellablePromise((resolve, reject) => {
            timeoutId = setTimeout(() => {
                fn(...args).then(resolve).catch(reject);
            }, delay);
        });

        return currentPromise.promise;
    };
}

// Example Function: Simulating an API call
function fetchData(query) {
    return new Promise((resolve) => {
        setTimeout(() => {
            resolve(`Fetched data for: ${query}`);
        }, 1000); // Simulates a delay of 1 second
    });
}

// Creating a debounced version of fetchData
const debouncedFetchData = debounceAsync(fetchData, 500);

// Usage of the debounced function
debouncedFetchData('query1').then(console.log).catch(handleFetchError);
debouncedFetchData('query2');
debouncedFetchData('query3');

// A simple error handler
function handleFetchError(err) {
    if (err.isCanceled) {
        console.log('Fetch canceled');
    } else {
        console.error('Error:', err);
    }
}
```

